import 'admin_parse.dart';
class AdminUserModel { const AdminUserModel({required this.id,required this.fullName,required this.roles,this.email,this.phone,this.status,this.masjidId,this.masjidName,this.createdAt,this.updatedAt});
factory AdminUserModel.fromJson(Map<String,dynamic> json)=>AdminUserModel(id: readString(json,['id','_id','userId']), fullName: readString(json,['fullName','name','displayName']), email: readNullableString(json,['email']), phone: readNullableString(json,['phone','phoneNumber','mobile']), status: readNullableString(json,['status']) ?? 'ACTIVE', masjidId: readNullableString(json,['masjidId']), masjidName: readNullableString(json,['masjidName']) ?? (json['masjid'] is Map<String,dynamic> ? readNullableString(json['masjid'] as Map<String,dynamic>, ['name','masjidName']) : null), roles: readRoles(json['roles']), createdAt: readNullableString(json,['createdAt']), updatedAt: readNullableString(json,['updatedAt']));
final String id, fullName; final String? email, phone, status, masjidId, masjidName, createdAt, updatedAt; final List<String> roles;}
